import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { describe, it } from "@jest/globals";
import { buildExpectedIntegration, excludedRuleIds, finalizedRuleIds, integrationTruthFile, machineProposalSha256, packetPath, packetSha256, preIntegrationCommit, provisionalRuleIds, responsePath, responseSha256, truthFiles, validateIntegration, validateStoredResponse } from "../../../scripts/preverif/integrate-rc5-maya-wave1-pdd-finality";

const root = process.cwd();
const sha = (value: string | Buffer) => crypto.createHash("sha256").update(value).digest("hex");
const read = <T>(file: string): T => JSON.parse(fs.readFileSync(path.join(root, file), "utf8")) as T;
describe("RC5-2 Maya Wave 1 DeepSeek integration", () => {
  it("validates response SHA, schema, exact rule set, machine rows, statuses, and strict provenance", () => { const { response } = validateStoredResponse(); assert.equal(sha(fs.readFileSync(responsePath)), responseSha256); assert.equal(response.decisions.length, 8); assert.deepEqual(response.decisions.filter((d: any) => d.reviewStatus === "REVIEWED").map((d: any) => d.stableRuleId), [...finalizedRuleIds]); assert.deepEqual(response.decisions.filter((d: any) => d.reviewStatus === "PROVISIONAL").map((d: any) => d.stableRuleId), [...provisionalRuleIds]); });
  it("integrates exactly two rows and preserves six provisional and two excluded rules", () => { const { integrated, before } = buildExpectedIntegration(); const rows = [...integrated.values()].flatMap((truth: any) => truth.decisions); assert.equal(rows.filter((row: any) => row.reviewStatus === "REVIEWED").length, 50); assert.equal(rows.filter((row: any) => row.reviewStatus === "PROVISIONAL").length, 8); assert.equal(new Set(rows.map((row: any) => row.stableRuleId)).size, 58); const old = new Map((before.get(integrationTruthFile)!.decisions as any[]).map((row) => [row.stableRuleId, row])); const next = new Map((integrated.get(integrationTruthFile)!.decisions as any[]).map((row) => [row.stableRuleId, row])); for (const id of excludedRuleIds) assert.deepEqual(next.get(id), old.get(id)); });
  it("preserves response and packet bytes, machine truth, and deterministic regeneration", () => { assert.equal(sha(fs.readFileSync(responsePath)), responseSha256); assert.equal(sha(fs.readFileSync(packetPath)), packetSha256); assert.equal(sha(fs.readFileSync("tests/fixtures/preverif/maya-forest-corridor-redd-belize-live/machine-proposal.json")), machineProposalSha256); assert.equal(validateIntegration(), true); const a = buildExpectedIntegration(); const b = buildExpectedIntegration(); assert.deepEqual([...a.integrated.entries()], [...b.integrated.entries()]); const manifest = read<any>("docs/roadmaps/interactive-evidence-review-mvp/rc/rc5/rc5-2-maya-wave-1-pdd-finality/integration-manifest.json"); assert.deepEqual(manifest.integratedTruthFiles, [integrationTruthFile]); assert.equal(manifest.packetShaUnchanged, true); assert.equal(manifest.responsePreservedByteForByte, true); assert.equal(manifest.unavailableInterpretationsPreservedAsProvisional, true); });
  it("detects response, packet, and machine SHA mutation without writing integration", () => { for (const [file, expected, pattern] of [[responsePath, responseSha256, /response SHA mismatch/], [packetPath, packetSha256, /packet SHA mismatch/], ["tests/fixtures/preverif/maya-forest-corridor-redd-belize-live/machine-proposal.json", machineProposalSha256, /machine proposal SHA changed/]] as const) { const target = path.join(root, file); const original = fs.readFileSync(target); try { fs.writeFileSync(target, Buffer.concat([original, Buffer.from("\n")])) ; assert.notEqual(sha(fs.readFileSync(target)), expected); assert.throws(() => validateStoredResponse(), pattern); } finally { fs.writeFileSync(target, original); } } });
  it("keeps historical truth reproducibility and every non-target row unchanged", () => { const { integrated, before } = buildExpectedIntegration(); for (const file of truthFiles) { const oldRows = new Map((before.get(file)!.decisions as any[]).map((row) => [row.stableRuleId, row])); const newRows = new Map((integrated.get(file)!.decisions as any[]).map((row) => [row.stableRuleId, row])); for (const [id, oldRow] of oldRows) if (file !== integrationTruthFile || ![...finalizedRuleIds, ...provisionalRuleIds].includes(id as any)) assert.deepEqual(newRows.get(id), oldRow, `${file}:${id}`); } assert.equal(preIntegrationCommit, "507822b92b64a12b5f71ca4ac0d3490379aa146f"); });
});
